def compute(vars):
    diluted_weighted_average_shares = vars["v1"]
    excluded_potential_shares = vars["v2"]
    total_diluted_weighted_average_shares = (
        diluted_weighted_average_shares + excluded_potential_shares
    )
    return {
        "value": total_diluted_weighted_average_shares,
        "trace": {
            "diluted_weighted_average_shares": diluted_weighted_average_shares,
            "excluded_potential_shares": excluded_potential_shares,
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": "shares",
            },
        },
    }
